import random, sys, json, copy
sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/tmp')
import algo, exact, fab, ref, gen

def run(seed):
    rng = random.Random(seed)
    profile, inc, x = gen.gen_profile(rng)
    m = exact.calib_model(profile)
    if not m['feasible']:
        # audit inconsistent proposals
        fabric, P = gen.gen_fabric(rng, K=profile['groups'])
        art = exact.calib_artifact(profile, m)
        K, E = exact.exact_edges(profile)
        assert algo.audit(profile, fabric, art) == {"valid": True}, 'honest inconsistent'
        assert algo.audit(profile, fabric, {"status":"inconsistent","cycle":[]}) == {"valid": False}
        assert algo.audit(profile, fabric, {"status":"inconsistent","cycle":art['cycle']+[art['cycle'][0]]}) == {"valid": False}
        bad = list(art['cycle']); 
        # break connection: swap two ids
        if len(bad) >= 2:
            bad[0], bad[1] = bad[1], bad[0]
            # may still connect by chance; verify semantically
            ok = exact.check_cycle(bad, K, E)
            assert (algo.audit(profile, fabric, {"status":"inconsistent","cycle":bad}) == {"valid": True}) == ok
        # "ok" plan artifact on inconsistent profile must be false
        assert algo.audit(profile, fabric, {"status":"ok"}) == {"valid": False}
        # out-of-range cycle id
        assert algo.audit(profile, fabric, {"status":"inconsistent","cycle":[10**6]}) == {"valid": False}
        return 'inconsistent ok'
    fabric, P = gen.gen_fabric(rng, K=profile['groups'])
    plan = algo.compile_plan(profile, fabric)
    assert algo.audit(profile, fabric, plan) == {"valid": True}
    if plan['guard_ns'] is None:
        # mutating peaks to finite breaks
        mut = copy.deepcopy(plan); mut['peaks_as'] = [0]*len(mut['peaks_as'])
        assert algo.audit(profile, fabric, mut) == {"valid": False}, 'peaks fake'
        mut = copy.deepcopy(plan); mut['guard_ns'] = fabric['guards_ns'][0]
        mut['bounds_as'] = [[[0]*fabric['n'] for _ in range(P)]]
        assert algo.audit(profile, fabric, mut) == {"valid": False}, 'guard fake'
        return 'no-guard ok'
    # mutations -> false
    def one():
        mut = copy.deepcopy(plan)
        kind = rng.randrange(14)
        p = rng.randrange(P); i = rng.randrange(fabric['n'])
        if kind == 0 and plan['bounds_as'][p][i] is not None:
            mut['bounds_as'][p][i] += 1
        elif kind == 1 and plan['age_rounds'][p][i] is not None:
            mut['age_rounds'][p][i] += 1
        elif kind == 2:
            mut['pred'][p][i] = None if plan['pred'][p][i] is not None else [0, -1]
        elif kind == 3:
            mut['warmup_cycle'] += 1
        elif kind == 4:
            mut['period_rounds'] += 1
        elif kind == 5:
            mut['peaks_as'][0] = None if mut['peaks_as'][0] is not None else 5
        elif kind == 6:
            gsz = len(fabric['guards_ns'])
            mut['guard_ns'] = fabric['guards_ns'][(gsz-1) - fabric['guards_ns'].index(plan['guard_ns'])]
            if mut['guard_ns'] == plan['guard_ns']:
                mut['warmup_cycle'] += 2
        elif kind == 7:
            mut['pred'][p][i] = [P*fabric['n']+1, -1]
        elif kind == 8:
            mut['pred'][p][i] = [0, 10**9]
        elif kind == 9:
            mut['bounds_as'][p][i] = True
        elif kind == 10:
            mut['bounds_as'][p][i] = 10**30
        elif kind == 11:
            mut['profile']['upper_ps'][0][0] += 10**12 if fabric['n'] else 1
        elif kind == 12 and plan['pred'][p][i] is not None:
            pv, kd = mut['pred'][p][i]
            mut['pred'][p][i] = [pv, kd+1]
        elif kind == 13:
            mut['age_rounds'][p][i] = None
        return mut
    for trial in range(30):
        mut = one()
        if json.dumps(mut, sort_keys=True) == json.dumps(plan, sort_keys=True):
            continue
        r = algo.audit(profile, fabric, mut)
        assert r == {"valid": False}, (seed, kind if False else trial, 'expected false', r)
    return 'plan/audit ok'

if __name__ == '__main__':
    n = int(sys.argv[1]) if len(sys.argv) > 1 else 60
    s0 = int(sys.argv[2]) if len(sys.argv) > 2 else 0
    for s in range(s0, s0+n):
        r = run(s)
    print('ADV ALL OK')
EOF
